const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const api=(path,options={})=>window.EHSApi.request(path,options);
const STATUS={draft:['작성중','draft'],received:['접수완료','received'],in_review:['검토중','in_review'],answered:['답변완료','answered'],closed:['종결','closed']};
const CATEGORY={general:'일반문의',safety:'안전',facility:'시설·설비',other:'기타'};
let currentUser=null,vocData={items:[],summary:{}},activeItem=null,pendingPhotos=[],busy=false,composerOpen=false,cameraStream=null,localImageUrl='',localImageScale=100,searchTimer=0;
const thumbnailTickets=new Map();

window.AttachmentPreview.init({
  getPreviewTicket:image=>api(`/api/voc/images/${encodeURIComponent(image.id)}/preview-ticket`,{method:'POST'}),
  download:image=>window.EHSApi.download(`/api/voc/images/${encodeURIComponent(image.id)}`,image.file_name),
  maxPreviewBytes:10*1024*1024,
  onError:error=>console.error('VOC image preview failed',error)
});

function statusBadge(value){const [label,cls]=STATUS[value]||[value||'-','closed'];return `<span class="status ${cls}">${label}</span>`}
function categoryBadge(value){return `<span class="category">${esc(CATEGORY[value]||'일반문의')}</span>`}
function formatDate(value){if(!value)return'-';const date=new Date(String(value).includes('T')?value:String(value).replace(' ','T')+'Z');if(Number.isNaN(date.getTime()))return esc(String(value).slice(0,16));return date.toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function formatBytes(value){const n=Number(value||0);if(n<1024)return `${n} B`;if(n<1024*1024)return `${Math.round(n/1024)} KB`;return `${Math.round(n/1024/1024*10)/10} MB`}
function showToast(message){const el=$('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.add('hidden'),2800)}
function goHome(){location.href='/home'}
$('homeBrand').onclick=goHome;$('homeBtn').onclick=goHome;$('logoutBtn').onclick=()=>window.EHSAuth.logout();$('refreshBtn').onclick=loadCases;$('newBtn').onclick=()=>openComposer();

function renderSummary(){const s=vocData.summary||{};const cards=currentUser.role==='admin'
  ? [['전체',Number(s.received||0)+Number(s.in_review||0)+Number(s.answered||0)+Number(s.closed||0),''],['접수완료',s.received,'received'],['검토중',s.in_review,'review'],['답변완료',s.answered,'answered'],['종결',s.closed,'closed']]
  : [['전체',Object.values(s).reduce((a,b)=>a+Number(b||0),0),''],['작성중',s.draft,'draft'],['접수완료',s.received,'received'],['검토중',s.in_review,'review'],['답변완료',Number(s.answered||0)+Number(s.closed||0),'answered']];
  $('summary').innerHTML=cards.map(([label,value,cls])=>`<div class="summary-card ${cls}"><span>${label}</span><b>${Number(value||0)}건</b></div>`).join('')
}

function renderList(){renderSummary();const items=vocData.items||[];if(!items.length){$('list').innerHTML='<div class="empty">등록된 VOC가 없습니다.</div>';return}const companyHead=currentUser.role==='admin'?'<th>협력사</th>':'';const companyCell=item=>currentUser.role==='admin'?`<td>${esc(item.company_name||'-')}</td>`:'';$('list').innerHTML=`<table class="voc-table"><thead><tr><th>상태</th><th>분류</th>${companyHead}<th>제목·내용</th><th>사진</th><th>접수일</th></tr></thead><tbody>${items.map(item=>`<tr data-id="${esc(item.id)}"><td>${statusBadge(item.status)}</td><td>${categoryBadge(item.category)}</td>${companyCell(item)}<td><span class="case-title">${esc(item.title)}</span><span class="case-snippet">${esc(item.content)}</span></td><td><span class="photo-count">▧ ${Number(item.image_count||0)}장</span></td><td>${esc(formatDate(item.submitted_at||item.created_at))}</td></tr>`).join('')}</tbody></table>`;$('list').querySelectorAll('tr[data-id]').forEach(row=>row.onclick=()=>openItem(row.dataset.id))}

async function loadCases(){const params=new URLSearchParams();const q=$('search').value.trim(),category=$('categoryFilter').value,status=$('statusFilter').value;if(q)params.set('q',q);if(category)params.set('category',category);if(status)params.set('status',status);$('list').innerHTML='<div class="loading">VOC 내역을 불러오는 중...</div>';try{vocData=await api(`/api/voc${params.size?`?${params}`:''}`);renderList()}catch(error){$('list').innerHTML=`<div class="error">${esc(error.message)}</div>`}}
$('categoryFilter').onchange=loadCases;$('statusFilter').onchange=loadCases;$('search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadCases,280)};

function clearPending(){for(const photo of pendingPhotos)URL.revokeObjectURL(photo.url);pendingPhotos=[]}
function closeMainModal(force=false){if(busy&&!force)return;if(composerOpen&&pendingPhotos.length&&!force&&!confirm('추가한 사진을 저장하지 않고 닫을까요?'))return;clearPending();activeItem=null;composerOpen=false;$('mainModal').classList.add('hidden');$('modalBody').innerHTML=''}
$('modalClose').onclick=()=>closeMainModal();$('mainModal').onclick=event=>{if(event.target===$('mainModal'))closeMainModal()};

function openModal(title,sub='',wide=false){$('modalTitle').textContent=title;$('modalSub').textContent=sub;$('modalCard').classList.toggle('wide',wide);$('mainModal').classList.remove('hidden')}
async function openItem(id){openModal('VOC 확인','불러오는 중...',true);$('modalBody').innerHTML='<div class="loading">접수내용을 불러오는 중...</div>';try{const data=await api(`/api/voc/${encodeURIComponent(id)}`);activeItem=data.item;if(currentUser.role==='partner'&&activeItem.status==='draft')openComposer(activeItem);else renderDetail(activeItem)}catch(error){$('modalBody').innerHTML=`<div class="error">${esc(error.message)}</div>`}}

function composerPhotoMarkup(){const stored=activeItem?.images||[];const cards=stored.map(image=>`<div class="photo-card"><img data-thumb-id="${esc(image.id)}" alt="${esc(image.file_name)}"><button class="photo-open" type="button" data-stored-open="${esc(image.id)}" aria-label="${esc(image.file_name)} 확대보기"></button><button class="photo-remove" type="button" data-stored-remove="${esc(image.id)}" aria-label="사진 삭제">×</button></div>`);cards.push(...pendingPhotos.map((photo,index)=>`<div class="photo-card"><img src="${esc(photo.url)}" alt="추가 사진 ${index+1}"><button class="photo-open" type="button" data-pending-open="${index}" aria-label="사진 확대보기"></button><button class="photo-remove" type="button" data-pending-remove="${index}" aria-label="사진 삭제">×</button><span class="photo-pending">추가됨</span></div>`));return cards.length?`<div class="photo-grid">${cards.join('')}</div>`:'<div class="photo-empty">클립보드, 카메라 또는 사진함에서 사진을 추가할 수 있습니다.</div>'}

function openComposer(item=null){activeItem=item||null;composerOpen=true;clearPending();openModal(item?'VOC 작성 계속':'VOC 접수',item?'작성중인 내용을 확인한 뒤 접수하세요.':'내용을 작성한 뒤 접수하세요.',false);$('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label for="vocCategory">분류</label><select id="vocCategory"><option value="general">일반문의</option><option value="safety">안전</option><option value="facility">시설·설비</option><option value="other">기타</option></select></div><div class="field"><label for="vocTitle">제목</label><input id="vocTitle" type="text" maxlength="120" placeholder="내용을 쉽게 구분할 수 있는 제목"></div><div class="field full"><label for="vocContent">내용 <span class="required">*</span></label><textarea id="vocContent" maxlength="5000" required placeholder="문의 또는 개선이 필요한 내용을 입력하세요."></textarea><div class="char-count" id="contentCount">0 / 5000</div></div></div><section class="photo-section"><div class="photo-head"><strong>사진</strong><span id="photoCount">0 / 5</span></div><div class="photo-tools"><button class="photo-tool" id="pastePhoto" type="button"><svg viewBox="0 0 24 24"><path d="M9 5h6M9 3h6v4H9zM7 5H5v16h14V5h-2"/></svg>클립보드 붙여넣기</button><button class="photo-tool" id="openCamera" type="button"><svg viewBox="0 0 24 24"><path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="4"/></svg>카메라</button><label class="photo-tool photo-tool-label" for="galleryPhotos"><svg viewBox="0 0 24 24"><path d="M4 4h16v16H4z"/><circle cx="9" cy="9" r="2"/><path d="m4 17 5-5 3 3 2-2 6 6"/></svg>사진함<input id="galleryPhotos" type="file" accept="image/*" multiple></label></div><div id="composerPhotos">${composerPhotoMarkup()}</div></section><div class="modal-actions"><span class="busy-state" id="composerBusy"></span><span class="grow"></span>${item?'<button class="btn danger" id="deleteDraft" type="button">작성내용 삭제</button>':''}<button class="btn" id="cancelCompose" type="button">닫기</button><button class="btn primary" id="submitVoc" type="button">접수하기</button></div>`;$('vocCategory').value=item?.category||'general';$('vocTitle').value=item?.title||'';$('vocContent').value=item?.content||'';updateContentCount();bindComposer()}

function bindComposer(){$('vocContent').oninput=updateContentCount;$('galleryPhotos').onchange=event=>addPhotoFiles([...event.target.files]);$('pastePhoto').onclick=readClipboardPhoto;$('openCamera').onclick=openCamera;$('cancelCompose').onclick=()=>closeMainModal();$('submitVoc').onclick=submitVoc;if($('deleteDraft'))$('deleteDraft').onclick=deleteDraft;bindComposerPhotos()}
function updateContentCount(){$('contentCount').textContent=`${$('vocContent').value.length} / 5000`}
function updatePhotoArea(){if(!$('composerPhotos'))return;$('composerPhotos').innerHTML=composerPhotoMarkup();$('photoCount').textContent=`${Number(activeItem?.images?.length||0)+pendingPhotos.length} / 5`;bindComposerPhotos()}
function bindComposerPhotos(){$('composerPhotos')?.querySelectorAll('[data-pending-open]').forEach(button=>button.onclick=()=>openLocalImage(pendingPhotos[Number(button.dataset.pendingOpen)]?.url));$('composerPhotos')?.querySelectorAll('[data-pending-remove]').forEach(button=>button.onclick=()=>removePending(Number(button.dataset.pendingRemove)));$('composerPhotos')?.querySelectorAll('[data-stored-open]').forEach(button=>button.onclick=()=>previewStored(button.dataset.storedOpen));$('composerPhotos')?.querySelectorAll('[data-stored-remove]').forEach(button=>button.onclick=()=>removeStored(button.dataset.storedRemove));hydrateThumbnails($('composerPhotos'),activeItem?.images||[])}

function imageExtension(name){return(String(name||'').split('.').pop()||'').toLowerCase()}
async function normalizePhoto(file){if(!(file instanceof File)||file.size<=0)throw new Error('사진 파일을 읽을 수 없습니다.');const supported=['jpg','jpeg','png','webp'].includes(imageExtension(file.name))&&['image/jpeg','image/png','image/webp'].includes(file.type);if(supported&&file.size<=8*1024*1024)return file;let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'})}catch{const url=URL.createObjectURL(file);try{bitmap=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('지원하지 않는 이미지 형식입니다.'));image.src=url})}finally{URL.revokeObjectURL(url)}}const max=2560,ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d',{alpha:false}).drawImage(bitmap,0,0,canvas.width,canvas.height);if(bitmap.close)bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw new Error('사진을 변환할 수 없습니다.');const stem=String(file.name||'photo').replace(/\.[^.]+$/,'').slice(0,80)||'photo';return new File([blob],`${stem}.jpg`,{type:'image/jpeg',lastModified:Date.now()})}
async function addPhotoFiles(files){const available=5-Number(activeItem?.images?.length||0)-pendingPhotos.length;if(available<=0){showToast('사진은 최대 5장까지 등록할 수 있습니다.');return}const selected=files.filter(file=>file?.type?.startsWith('image/')||/\.(jpe?g|png|webp|heic|heif)$/i.test(file?.name||'')).slice(0,available);if(!selected.length){showToast('이미지 파일을 선택하세요.');return}for(const file of selected){try{const normalized=await normalizePhoto(file);if(normalized.size>10*1024*1024)throw new Error('사진은 한 장당 10MB 이하만 등록할 수 있습니다.');pendingPhotos.push({file:normalized,url:URL.createObjectURL(normalized)})}catch(error){showToast(error.message)}}updatePhotoArea()}
function removePending(index){const [photo]=pendingPhotos.splice(index,1);if(photo)URL.revokeObjectURL(photo.url);updatePhotoArea()}
async function removeStored(id){if(!confirm('이 사진을 삭제할까요?'))return;try{await api(`/api/voc/images/${encodeURIComponent(id)}`,{method:'DELETE'});activeItem.images=activeItem.images.filter(image=>image.id!==id);updatePhotoArea();showToast('사진을 삭제했습니다.')}catch(error){alert(error.message)}}
function previewStored(id){const image=activeItem?.images?.find(item=>item.id===id);if(image)window.AttachmentPreview.open(image)}
async function thumbnailSource(image){if(thumbnailTickets.has(image.id))return thumbnailTickets.get(image.id);const pending=api(`/api/voc/images/${encodeURIComponent(image.id)}/preview-ticket`,{method:'POST'}).then(data=>data.source_url).catch(()=>null);thumbnailTickets.set(image.id,pending);return pending}
async function hydrateThumbnails(root,images){if(!root)return;for(const image of images){const element=root.querySelector(`[data-thumb-id="${CSS.escape(image.id)}"]`);if(!element||element.src)continue;const source=await thumbnailSource(image);if(source&&element.isConnected)element.src=source}}

async function readClipboardPhoto(){if(!navigator.clipboard?.read){showToast('이미지를 복사한 뒤 Ctrl+V를 눌러주세요.');return}try{const items=await navigator.clipboard.read(),files=[];for(const item of items){const type=item.types.find(value=>value.startsWith('image/'));if(type){const blob=await item.getType(type);files.push(new File([blob],`clipboard-${Date.now()}.${type.includes('png')?'png':'jpg'}`,{type}))}}if(!files.length){showToast('클립보드에서 이미지를 찾지 못했습니다.');return}await addPhotoFiles(files)}catch{showToast('이미지를 복사한 뒤 Ctrl+V를 눌러주세요.')}}
document.addEventListener('paste',event=>{if(!composerOpen||currentUser?.role!=='partner')return;const files=[...(event.clipboardData?.files||[])].filter(file=>file.type.startsWith('image/'));if(!files.length)return;event.preventDefault();addPhotoFiles(files)});

async function openCamera(){if(!navigator.mediaDevices?.getUserMedia){$('cameraFallback').click();return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});$('cameraVideo').srcObject=cameraStream;$('cameraModal').classList.remove('hidden');await $('cameraVideo').play()}catch{$('cameraFallback').click()}}
function closeCamera(){for(const track of cameraStream?.getTracks?.()||[])track.stop();cameraStream=null;$('cameraVideo').srcObject=null;$('cameraModal').classList.add('hidden')}
$('cameraClose').onclick=closeCamera;$('cameraModal').onclick=event=>{if(event.target===$('cameraModal'))closeCamera()};$('cameraCapture').onclick=async()=>{const video=$('cameraVideo');if(!video.videoWidth){showToast('카메라 화면을 준비하는 중입니다.');return}const max=2560,ratio=Math.min(1,max/Math.max(video.videoWidth,video.videoHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(video.videoWidth*ratio);canvas.height=Math.round(video.videoHeight*ratio);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));closeCamera();if(blob)await addPhotoFiles([new File([blob],`camera-${Date.now()}.jpg`,{type:'image/jpeg'})])};$('cameraFallback').onchange=event=>{addPhotoFiles([...event.target.files]);event.target.value=''};

function setComposerBusy(value,label='처리 중...'){busy=value;document.querySelectorAll('#modalBody button,#modalBody input,#modalBody select,#modalBody textarea').forEach(el=>el.disabled=value);if($('composerBusy'))$('composerBusy').textContent=value?label:''}
async function submitVoc(){const content=$('vocContent').value.trim();if(!content){$('vocContent').focus();showToast('내용을 입력하세요.');return}setComposerBusy(true,'내용 저장 중...');try{const payload={category:$('vocCategory').value,title:$('vocTitle').value.trim(),content};let item=activeItem;if(!item)item=(await api('/api/voc/drafts',{method:'POST',body:JSON.stringify(payload)})).item;else item=(await api(`/api/voc/${encodeURIComponent(item.id)}`,{method:'PATCH',body:JSON.stringify(payload)})).item;activeItem=item;while(pendingPhotos.length){const state=$('composerBusy');if(state)state.textContent=`사진 등록 중 ${Number(activeItem.images?.length||0)+1}/${Number(activeItem.images?.length||0)+pendingPhotos.length}`;const photo=pendingPhotos[0],form=new FormData();form.append('file',photo.file);const added=(await api(`/api/voc/${encodeURIComponent(item.id)}/images`,{method:'POST',body:form})).image;activeItem.images=activeItem.images||[];activeItem.images.push(added);pendingPhotos.shift();URL.revokeObjectURL(photo.url)}if($('composerBusy'))$('composerBusy').textContent='VOC 접수 중...';await api(`/api/voc/${encodeURIComponent(item.id)}/submit`,{method:'POST',body:'{}'});setComposerBusy(false);closeMainModal(true);showToast('VOC가 접수되었습니다.');await loadCases()}catch(error){setComposerBusy(false);if(activeItem){updatePhotoArea();showToast('작성내용이 저장되었습니다. 다시 접수해 주세요.')}alert(error.message)}}
async function deleteDraft(){if(!activeItem||!confirm('작성중인 VOC와 등록한 사진을 삭제할까요?'))return;setComposerBusy(true,'삭제 중...');try{await api(`/api/voc/${encodeURIComponent(activeItem.id)}`,{method:'DELETE'});setComposerBusy(false);closeMainModal(true);showToast('작성내용을 삭제했습니다.');await loadCases()}catch(error){setComposerBusy(false);alert(error.message)}}

function imageCards(images){if(!images?.length)return'<div class="empty" style="padding:20px">등록된 사진이 없습니다.</div>';return `<div class="detail-photos">${images.map(image=>`<button class="detail-photo" type="button" data-preview="${esc(image.id)}" title="${esc(image.file_name)}"><img data-thumb-id="${esc(image.id)}" alt="${esc(image.file_name)}"><span class="hidden">${esc(formatBytes(image.file_size))}</span></button>`).join('')}</div>`}
function renderDetail(item){composerOpen=false;openModal(currentUser.role==='admin'?'VOC 접수내용':'VOC 처리현황',`${item.company_name||''} · ${formatDate(item.submitted_at||item.created_at)}`,true);$('modalBody').innerHTML=`<div class="detail-meta">${statusBadge(item.status)}${categoryBadge(item.category)}<span class="detail-date">${esc(formatDate(item.submitted_at||item.created_at))}</span></div><div class="detail-grid"><div><section class="detail-block"><div class="detail-title">${esc(item.title)}</div><div class="detail-content">${esc(item.content)}</div>${item.admin_reply?`<div class="reply"><b>관리자 답변</b><br>${esc(item.admin_reply)}</div>`:''}</section><section class="detail-block" style="margin-top:12px"><h3>사진 ${Number(item.image_count||0)}장</h3>${imageCards(item.images)}</section></div>${currentUser.role==='admin'?`<aside class="detail-block admin-box"><h3>처리상태 및 답변</h3><select id="adminStatus"><option value="received">접수완료</option><option value="in_review">검토중</option><option value="answered">답변완료</option><option value="closed">종결</option></select><textarea id="adminReply" maxlength="4000" placeholder="협력사에 전달할 답변을 입력하세요.">${esc(item.admin_reply||'')}</textarea><button class="btn primary" id="saveAdmin" type="button">처리내용 저장</button><div class="busy-state" id="adminBusy"></div></aside>`:''}</div><div class="modal-actions">${currentUser.role==='admin'?'<button class="btn danger" id="deleteAdminCase" type="button">VOC 삭제</button>':''}<span class="grow"></span><button class="btn" id="closeDetail" type="button">닫기</button></div>`;$('modalBody').querySelectorAll('[data-preview]').forEach(button=>button.onclick=()=>previewStored(button.dataset.preview));hydrateThumbnails($('modalBody'),item.images||[]);$('closeDetail').onclick=()=>closeMainModal();if(currentUser.role==='admin'){$('adminStatus').value=item.status;$('saveAdmin').onclick=saveAdmin;$('deleteAdminCase').onclick=deleteAdminCase}}
async function saveAdmin(){const status=$('adminStatus').value,admin_reply=$('adminReply').value.trim();if(['answered','closed'].includes(status)&&!admin_reply){$('adminReply').focus();showToast('답변을 입력하세요.');return}$('saveAdmin').disabled=true;$('adminBusy').textContent='저장 중...';try{const data=await api(`/api/admin/voc/${encodeURIComponent(activeItem.id)}`,{method:'PATCH',body:JSON.stringify({status,admin_reply})});activeItem=data.item;renderDetail(activeItem);showToast('처리내용을 저장했습니다.');await loadCases()}catch(error){$('saveAdmin').disabled=false;$('adminBusy').textContent='';alert(error.message)}}
async function deleteAdminCase(){if(!activeItem||!confirm('이 VOC와 첨부된 사진을 모두 삭제할까요? 삭제 후 복구할 수 없습니다.'))return;const button=$('deleteAdminCase');button.disabled=true;try{await api(`/api/admin/voc/${encodeURIComponent(activeItem.id)}`,{method:'DELETE'});closeMainModal(true);showToast('VOC를 삭제했습니다.');await loadCases()}catch(error){button.disabled=false;alert(error.message)}}

function openLocalImage(url){if(!url)return;localImageUrl=url;localImageScale=100;$('imageView').src=url;$('imageModal').classList.remove('hidden');$('imageView').onload=fitLocalImage;updateLocalImage()}
function updateLocalImage(){$('imagePercent').textContent=`${Math.round(localImageScale)}%`;const image=$('imageView');if(image.naturalWidth)image.style.width=`${Math.max(1,Math.round(image.naturalWidth*localImageScale/100))}px`}
function fitLocalImage(){const image=$('imageView'),stage=$('imageStage');if(!image.naturalWidth||!image.naturalHeight)return;localImageScale=Math.min(100,(stage.clientWidth-30)/image.naturalWidth*100,(stage.clientHeight-30)/image.naturalHeight*100);updateLocalImage()}
function closeLocalImage(){$('imageModal').classList.add('hidden');$('imageView').src='';localImageUrl=''}
$('imageFit').onclick=fitLocalImage;$('imageMinus').onclick=()=>{localImageScale=Math.max(10,localImageScale-10);updateLocalImage()};$('imagePlus').onclick=()=>{localImageScale=Math.min(500,localImageScale+10);updateLocalImage()};$('imagePercent').onclick=()=>{localImageScale=100;updateLocalImage()};$('imageClose').onclick=closeLocalImage;$('imageModal').onclick=event=>{if(event.target===$('imageModal'))closeLocalImage()};

(async()=>{try{currentUser=await window.EHSAuth.requireUser();window.__EHS_PAGE_USER=currentUser;document.dispatchEvent(new CustomEvent('ehs:user-ready',{detail:currentUser}));const admin=currentUser.role==='admin';$('pageTitle').textContent=admin?'VOC 접수현황':'VOC 건의';$('pageMeta').textContent=admin?'협력사 VOC의 접수내용과 사진을 확인하고 처리합니다.':'EHS 관련 문의와 개선 의견을 접수하고 처리상태를 확인합니다.';$('listTitle').textContent=admin?'전체 VOC 접수현황':'내 VOC 접수내역';$('newBtn').classList.toggle('hidden',admin);if(admin)$('statusFilter').querySelector('option[value="draft"]').remove();$('userLabel').textContent=[currentUser.company_name,currentUser.position,currentUser.name].filter(Boolean).join(' · ')||currentUser.email||'';await loadCases()}catch(error){if(error?.status===401)return;document.querySelector('.shell').innerHTML=`<div class="error">${esc(window.EHSApi?.describe?window.EHSApi.describe(error):error.message)}</div>`}})();
